import React, { useState, useEffect, useRef } from 'react';
import { Card, Button, Alert, api } from '../App';

// Always show 5 party columns (P1..P5)
const MAX_P = 5;

export default function MarkingPage() {
  const [allParties,  setAllParties]  = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selParties,  setSelParties]  = useState([]);  // ordered list [{id,name,code}]
  const [saleNo,      setSaleNo]      = useState('');
  const [partySearch, setPartySearch] = useState('');

  // Skip options (moved from Mapping)
  const [skipBlankLsp, setSkipBlankLsp] = useState(true);
  const [skipDupBGG,   setSkipDupBGG]   = useState(false);

  // Preview result
  const [preview,   setPreview]   = useState([]);  // array of lots
  const [skipRows,  setSkipRows]  = useState({});  // catalogue_id → bool
  // manualP: catalogue_id → { P1: partyCode, P2: ..., P3: ..., P4: ..., P5: ... }
  const [manualP,   setManualP]   = useState({});
  const [dupWarn,   setDupWarn]   = useState([]);

  const [loading, setLoading] = useState(false);
  const [saving,  setSaving]  = useState(false);
  const [alert,   setAlert]   = useState(null);

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(() => ({ data: [] })),
      api.get('/import/sale-numbers').catch(() => ({ data: [] }))
    ]).then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  const toggleParty = (p) => {
    setSelParties(prev => {
      const exists = prev.find(x => x.id === p.id);
      if (exists) return prev.filter(x => x.id !== p.id);
      if (prev.length >= MAX_P) {
        setAlert({ msg: `Max ${MAX_P} parties can be selected at once`, type: 'warning' });
        return prev;
      }
      return [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }];
    });
  };

  const filteredParties = allParties.filter(p =>
    p.party_name.toLowerCase().includes(partySearch.toLowerCase()) ||
    p.party_code.toLowerCase().includes(partySearch.toLowerCase())
  );

  const selectAll   = () => setSelParties(filteredParties.slice(0, MAX_P).map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })));
  const deselectAll = () => setSelParties([]);

  const runPreview = async () => {
    if (!selParties.length || !saleNo) { setAlert({ msg: 'Select at least one party and sale number', type: 'error' }); return; }
    setLoading(true); setAlert(null); setDupWarn([]);
    try {
      const r = await api.post('/marking/preview', {
        party_ids:   selParties.map(p => p.id),
        sale_no:     saleNo,
        skip_blank_lsp: skipBlankLsp,
        skip_dup_broker_garden_grade: skipDupBGG
      });
      setPreview(r.data.lots || []);
      setSkipRows({});
      // Init manualP with auto-assigned parties
      const initManual = {};
      (r.data.lots || []).forEach(lot => {
        const cols = {};
        // party_cols from backend: { P1: {party_code,...}, P2: ... }
        for (let i = 1; i <= MAX_P; i++) {
          const pc = lot.party_cols?.[`P${i}`];
          cols[`P${i}`] = pc ? pc.party_code : '';
        }
        initManual[lot.catalogue_id] = cols;
      });
      setManualP(initManual);
      if (!r.data.lots?.length) setAlert({ msg: 'No lots found. Check Party Master grade/garden mappings.', type: 'warning' });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setLoading(false); }
  };

  const setPartyCell = (catalogueId, pKey, code) => {
    setManualP(prev => ({
      ...prev,
      [catalogueId]: { ...(prev[catalogueId] || {}), [pKey]: code.toUpperCase() }
    }));
  };

  const save = async () => {
    const warnings = [];
    const markings = [];

    for (const lot of preview) {
      if (skipRows[lot.catalogue_id]) continue;
      const cols = manualP[lot.catalogue_id] || {};

      // Each P column = one marking row for that party (if code is filled)
      for (let i = 1; i <= MAX_P; i++) {
        const code = (cols[`P${i}`] || '').trim().toUpperCase();
        if (!code) continue;

        const party = allParties.find(p => p.party_code === code);
        if (!party) { warnings.push(`P${i}: code "${code}" not found — skipped`); continue; }

        markings.push({
          sale_no:   saleNo,
          party_id:  party.id,
          party_name: party.party_name,
          party_code: party.party_code,
          garden:    lot.garden,
          grade:     lot.grade,
          lot_no:    lot.lot_no,
          broker:    lot.broker,
          bags:      lot.bags,
          net_wt:    lot.net_wt,
          gp_date:   lot.gp_date,
          min_price: lot.min_deal_price,
          max_price: lot.max_deal_price
        });
      }
    }

    if (warnings.length) setDupWarn(warnings);
    if (!markings.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }

    setSaving(true);
    try {
      const r = await api.post('/marking/save-v2', { markings, sale_no: saleNo });
      setAlert({ msg: `✅ ${r.data.saved} markings saved.${r.data.duplicates ? ` ${r.data.duplicates} duplicates skipped.` : ''}`, type: 'success' });
      if (r.data.warnings?.length) setDupWarn(prev => [...prev, ...r.data.warnings]);
      setPreview([]);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setSaving(false); }
  };

  const activeCount = preview.filter(r => !skipRows[r.catalogue_id]).length;

  // Sorted party list for the full display (not scrolling) — show all
  const partyHeaders = selParties.map((p, i) => ({ key: `P${i+1}`, code: p.party_code, name: p.party_name }));

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 14 }}>
        Select up to 5 parties. Each lot row has P1–P5 columns. Parties auto-fill based on mapping; manually edit any cell.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}
      {dupWarn.length > 0 && (
        <div style={{ background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8, padding: '8px 14px', marginBottom: 12, fontSize: 12, color: '#92400e' }}>
          {dupWarn.map((w, i) => <div key={i}>{w}</div>)}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr', gap: 14, marginBottom: 14 }}>
        {/* ── LEFT: Party selector ── */}
        <Card style={{ padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 13, color: '#1a3c5e', marginBottom: 8 }}>
            Select Parties <span style={{ fontWeight: 400, color: '#888', fontSize: 11 }}>(max {MAX_P})</span>
          </div>
          <input value={partySearch} onChange={e => setPartySearch(e.target.value)} placeholder="Search…"
            style={{ width: '100%', padding: '6px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 12, marginBottom: 8 }} />
          <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
            <Button size="sm" variant="outline" onClick={selectAll}   style={{ flex: 1, fontSize: 11 }}>✓ Select All</Button>
            <Button size="sm" variant="outline" onClick={deselectAll} style={{ flex: 1, fontSize: 11 }}>✕ Clear</Button>
          </div>

          {/* Full party list — all visible */}
          <div style={{ maxHeight: 420, overflowY: 'auto', border: '1px solid #f0f4f8', borderRadius: 6 }}>
            {filteredParties.map(p => {
              const idx = selParties.findIndex(x => x.id === p.id);
              const sel = idx >= 0;
              return (
                <div key={p.id} onClick={() => toggleParty(p)}
                  style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', cursor: 'pointer',
                    background: sel ? '#dbeafe' : '#fff', borderBottom: '1px solid #f0f4f8', userSelect: 'none' }}>
                  <div style={{ width: 18, height: 18, borderRadius: 4, border: `2px solid ${sel ? '#1a3c5e' : '#cbd5e0'}`,
                    background: sel ? '#1a3c5e' : '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    {sel && <span style={{ color: '#fff', fontSize: 11, fontWeight: 700 }}>✓</span>}
                  </div>
                  <div style={{ flex: 1, fontSize: 12 }}>
                    <span style={{ fontWeight: 700, color: '#1a3c5e' }}>[{p.party_code}]</span>
                    <span style={{ marginLeft: 4 }}>{p.party_name}</span>
                  </div>
                  {sel && (
                    <span style={{ background: '#1a3c5e', color: '#fff', fontSize: 10, fontWeight: 700, padding: '1px 6px', borderRadius: 99, flexShrink: 0 }}>
                      P{idx + 1}
                    </span>
                  )}
                </div>
              );
            })}
          </div>

          {selParties.length > 0 && (
            <div style={{ marginTop: 8, background: '#eff6ff', padding: '6px 10px', borderRadius: 6, fontSize: 11 }}>
              {selParties.map((p, i) => (
                <span key={p.id} style={{ marginRight: 8 }}><b>P{i+1}</b>: {p.party_code}</span>
              ))}
            </div>
          )}
        </Card>

        {/* ── RIGHT: Sale + Skip options + Action ── */}
        <Card style={{ padding: 14, alignSelf: 'start' }}>
          <div style={{ fontWeight: 700, fontSize: 13, color: '#1a3c5e', marginBottom: 12 }}>Sale & Options</div>

          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap', marginBottom: 16 }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>Sale Number *</label>
              <select value={saleNo} onChange={e => setSaleNo(e.target.value)}
                style={{ padding: '8px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
                <option value="">Select sale…</option>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
              </select>
            </div>
            <Button onClick={runPreview} disabled={loading || !selParties.length || !saleNo} variant="primary" style={{ padding: '8px 24px' }}>
              {loading ? '⏳ Loading…' : '🔍 Preview Lots'}
            </Button>
            {preview.length > 0 && (
              <Button onClick={save} disabled={saving || activeCount === 0} variant="success" style={{ padding: '8px 24px' }}>
                {saving ? 'Saving…' : `💾 Save ${activeCount} Lots`}
              </Button>
            )}
          </div>

          {/* Skip options */}
          <div style={{ borderTop: '1px solid #f0f4f8', paddingTop: 12 }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: '#555', marginBottom: 8 }}>Skip Options</div>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer', marginBottom: 8 }}>
              <input type="checkbox" checked={skipBlankLsp} onChange={e => setSkipBlankLsp(e.target.checked)} style={{ width: 15, height: 15 }} />
              Want to skip lots when Last Sale Price is blank [Y/N]
            </label>
            <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer' }}>
              <input type="checkbox" checked={skipDupBGG} onChange={e => setSkipDupBGG(e.target.checked)} style={{ width: 15, height: 15 }} />
              Want to skip extra lots when Broker, Garden &amp; Grade is same [Y/N]
            </label>
          </div>

          {preview.length > 0 && (
            <div style={{ marginTop: 12, fontSize: 12, color: '#555' }}>
              <b>{preview.length}</b> lots · <b style={{ color: '#1a7a4a' }}>{activeCount}</b> active
            </div>
          )}
        </Card>
      </div>

      {/* ── MARKING TABLE ── */}
      {preview.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '10px 16px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>TSDATA — Sale #{saleNo}</div>
            <div style={{ fontSize: 12, opacity: 0.8 }}>{preview.length} lots</div>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', width: 36 }}>Skip</th>
                  {/* P1..P5 — always show all 5 */}
                  {[1,2,3,4,5].map(i => {
                    const ph = partyHeaders[i-1];
                    return (
                      <th key={i} style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', background: ph ? '#1a3c5e' : '#2d4a6b', minWidth: 64 }}>
                        P{i}
                        {ph && <div style={{ fontSize: 9, fontWeight: 400, opacity: 0.8 }}>{ph.code}</div>}
                      </th>
                    );
                  })}
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Bro</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Lot</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap', minWidth: 120 }}>Garden</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Grd</th>
                  <th style={{ padding: '8px 8px', textAlign: 'center',fontWeight: 600, whiteSpace: 'nowrap', minWidth: 100 }}>Rate (Min-Max)</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>Qty</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>NWt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>GP Dt</th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  let lastBroker = null;
                  return preview.map((row, i) => {
                    const skip = !!skipRows[row.catalogue_id];
                    const brokerHeader = row.broker !== lastBroker;
                    lastBroker = row.broker;
                    const cols = manualP[row.catalogue_id] || {};

                    const rateDisplay = () => {
                      const mn = row.min_deal_price, mx = row.max_deal_price;
                      if (!mn && !mx) return <span style={{ color: '#ccc' }}>—</span>;
                      if (mn && mx && Math.abs(parseFloat(mn) - parseFloat(mx)) > 0.5)
                        return <span style={{ color: '#1a3c5e', fontWeight: 700 }}>{Number(mn).toFixed(0)}-{Number(mx).toFixed(0)}</span>;
                      return <span style={{ color: '#1a3c5e', fontWeight: 700 }}>{Number(mn || mx).toFixed(0)}/-</span>;
                    };

                    return (
                      <React.Fragment key={row.catalogue_id}>
                        {brokerHeader && (
                          <tr>
                            <td colSpan={13} style={{ background: '#e8f0fe', padding: '4px 10px', fontWeight: 700, fontSize: 11, color: '#1a3c5e', borderBottom: '1px solid #c7d2fe', borderTop: '1px solid #c7d2fe' }}>
                              Broker: {row.broker}
                            </td>
                          </tr>
                        )}
                        <tr style={{ borderBottom: '1px solid #f0f4f8', background: skip ? '#fff5f5' : (i % 2 === 0 ? '#fff' : '#fafbfc'), opacity: skip ? 0.4 : 1 }}>
                          {/* Skip */}
                          <td style={{ padding: '4px 6px', textAlign: 'center' }}>
                            <input type="checkbox" checked={skip}
                              onChange={() => setSkipRows(s => ({ ...s, [row.catalogue_id]: !s[row.catalogue_id] }))} />
                          </td>

                          {/* P1..P5 editable cells */}
                          {[1,2,3,4,5].map(pi => {
                            const pKey = `P${pi}`;
                            const val = cols[pKey] || '';
                            const isAutoFilled = selParties[pi-1] && val === selParties[pi-1]?.party_code;
                            return (
                              <td key={pi} style={{ padding: '4px 4px', textAlign: 'center' }}>
                                <input
                                  value={val}
                                  onChange={e => setPartyCell(row.catalogue_id, pKey, e.target.value)}
                                  placeholder={`P${pi}`}
                                  maxLength={5}
                                  disabled={skip}
                                  style={{
                                    width: 56, padding: '3px 4px', textAlign: 'center',
                                    border: `1.5px solid ${val ? (isAutoFilled ? '#1a7a4a' : '#f59e0b') : '#e2e8f0'}`,
                                    borderRadius: 5, fontSize: 11, fontFamily: 'monospace',
                                    background: val ? (isAutoFilled ? '#f0fdf4' : '#fffbeb') : '#fff',
                                    color: val ? (isAutoFilled ? '#166534' : '#92400e') : '#aaa',
                                    fontWeight: val ? 700 : 400,
                                    textTransform: 'uppercase'
                                  }}
                                />
                              </td>
                            );
                          })}

                          <td style={{ padding: '4px 8px', color: '#555', fontWeight: 600, fontSize: 11 }}>{row.broker}</td>
                          <td style={{ padding: '4px 8px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                          <td style={{ padding: '4px 8px', fontWeight: 700, color: '#1a3c5e', maxWidth: 140, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{row.garden}</td>
                          <td style={{ padding: '4px 8px' }}>
                            <span style={{ background: '#dbeafe', color: '#1e40af', padding: '1px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                          </td>
                          {/* Rate — read only, shows min-max from sold list */}
                          <td style={{ padding: '4px 8px', textAlign: 'center', fontSize: 12 }}>{rateDisplay()}</td>
                          <td style={{ padding: '4px 8px', textAlign: 'right', fontWeight: 600 }}>{row.bags || '—'}</td>
                          <td style={{ padding: '4px 8px', textAlign: 'right' }}>{row.net_wt || '—'}</td>
                          <td style={{ padding: '4px 8px', fontSize: 11, color: '#888', whiteSpace: 'nowrap' }}>
                            {row.gp_date ? new Date(row.gp_date).toLocaleDateString('en-IN', { day:'2-digit', month:'2-digit' }) : '—'}
                          </td>
                        </tr>
                      </React.Fragment>
                    );
                  });
                })()}
              </tbody>
            </table>
          </div>

          {/* Legend */}
          <div style={{ padding: '8px 16px', background: '#f8fafc', borderTop: '1px solid #f0f4f8', fontSize: 11, color: '#888', display: 'flex', gap: 20 }}>
            <span><span style={{ background: '#f0fdf4', border: '1.5px solid #1a7a4a', borderRadius: 3, padding: '0 6px', fontWeight: 700, color: '#166534', fontFamily: 'monospace' }}>AA</span> Auto-assigned from selected parties</span>
            <span><span style={{ background: '#fffbeb', border: '1.5px solid #f59e0b', borderRadius: 3, padding: '0 6px', fontWeight: 700, color: '#92400e', fontFamily: 'monospace' }}>AA</span> Manually entered</span>
            <span>Rate column = Min–Max from Sold List (read-only)</span>
          </div>
        </Card>
      )}
    </div>
  );
}
